def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 8)]
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    regions = []
    while unseen:
        start = unseen.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p)
                    comp.add(p)
                    stack.append(p)
        regions.append(comp)

    # The marker cluster encodes the colors of the large silhouette's
    # separate blocks in the same top-to-bottom order.
    regions.sort(key=lambda comp: (sum(r for r,c in comp)/len(comp),
                                   sum(c for r,c in comp)/len(comp)))
    marker_colors = sorted(markers, key=lambda m: (m[0], m[1]))
    colors = []
    for comp in regions:
        cr = sum(r for r,c in comp)/len(comp)
        cc = sum(c for r,c in comp)/len(comp)
        # Rank marker positions by their vertical/horizontal placement.
        colors.append(min(markers, key=lambda m:
                          (m[0]-cr/max(1,h)*max(1,h))**2 +
                          (m[1]-cc/max(1,w)*max(1,w))**2)[2])
    # When there are several regions, use the marker colors in spatial order.
    if len(regions) == 3:
        unique = []
        for _,_,v in marker_colors:
            if v not in unique:
                unique.append(v)
        if len(unique) >= 3:
            colors = unique[:3]
    for comp, color in zip(regions, colors):
        for r,c in comp:
            out[r][c] = color
    return out
